def apply_transform(grid, W, shifts):
    """Apply constant per-color shifts with modulo wrapping."""
    result = [[0]*W for _ in range(len(grid))]
    for y in range(len(grid)):
        for x in range(W):
            c = grid[y][x]
            if c != 0:
                dc = shifts.get(c, 0)
                nx = (x + dc) % W
                result[y][nx] = c
    return result

